public interface IModemVisitor { }                       // degenerate base, no members
public interface IZoomVisitor : IModemVisitor { void Visit(Zoom zoom); }

public sealed class Zoom : Modem
{
    public override void Accept(IModemVisitor visitor)
    {
        if (visitor is IZoomVisitor typed) typed.Visit(this);
        else Logger.Log("this visitor cannot visit Zoom");
    }
}
